{# SOURCE: https://github.com/churnish/web-clipper-templates #}{# Lines holding only tags print nothing. In regexes, \x22 is a double quote. #}{% set name = meta:property:og:title|replace:"/ on TikTok.*$/s":""|escape_md %}
{# Caption HTML: <br> marks line breaks; mentions and hashtags are links. #}{% set caption = selectorHtml:#media-card-0 [data-e2e="video-desc"]|first|replace:"/<br[^>]*>/g":"\n"|replace:"/<a [^>]*?href=\x22(\/[^\x22]*)\x22[^>]*>(.*?)<\/a>/gs":"[$2](https://www.tiktok.com$1)"|replace:"/<[^>]*>/g":""|replace:"/&nbsp;/g":" "|replace:"/&lt;/g":"<"|replace:"/&gt;/g":">"|replace:"/&amp;/g":"&"|replace:"/[\u200B\u2060-\u2064\uFEFF]/g":""|replace:"#":"\\\\#"|replace:"/ +$/gm":""|trim|replace:"/^./s":":** $&"|replace:"/^$/":"**" %}
{% set cover = selector:#media-card-0 picture img?src|first %}
**🩳 {{name}}{{caption}}

{% if cover %}![|392]({{cover}}){% endif %}
